LEGACY_DARWIN='package syncfs\n\nimport (\n\t"fmt"\n\n\t"golang.org/x/sys/unix"\n)\n\nfunc surveyMountFD(fd int) (string, error) {\n\tvar s unix.Statfs_t\n\tif err := unix.Fstatfs(fd, &s); err != nil {\n\t\treturn "", err\n\t}\n\treturn surveyDarwinMountIdentity(s)\n}\n\n// Darwin exposes no STATX_MNT_ID equivalent here. Pair its descriptor-reported\n// filesystem ID with the nonempty reported mountpoint, including same-Fsid\n// mounts that a filesystem-ID-only comparison would conflate.\nfunc surveyDarwinMountIdentity(s unix.Statfs_t) (string, error) {\n return fmt.Sprintf("%x", s.Fsid.Val), nil\n}\n\nfunc surveyMountAt(fd int, name string) (string, error) {\n\tchild, err := unix.Openat(fd, name, unix.O_EVTONLY|unix.O_SYMLINK|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)\n\tif err != nil {\n\t\treturn "", err\n\t}\n\tdefer unix.Close(child)\n\treturn surveyMountFD(child)\n}\n'
ORIGINAL_LINUX='package syncfs\n\nimport (\n\t"context"\n\t"fmt"\n\t"io"\n\t"math"\n\t"os"\n\n\t"golang.org/x/sys/unix"\n)\n\nconst maxWorkspaceSurveyEntries = 100000\nconst maxWorkspaceSurveyDepth = 128\n\n// WorkspaceAllocation is a bounded observation of st_blocks in one marked\n// private workspace. Hard links, clones and shared filesystem blocks may be\n// counted more than once; this is never exclusive reclamation evidence.\ntype WorkspaceAllocation struct {\n\tEntries        int\n\tAllocatedBytes int64\n}\n\nfunc surveyStable(a, b unix.Stat_t) bool {\n\treturn stableStat(a, b) && a.Blocks == b.Blocks && a.Nlink == b.Nlink\n}\n\nfunc (v *WorkspaceAllocation) add(st unix.Stat_t) error {\n\tif v.Entries >= maxWorkspaceSurveyEntries || st.Blocks < 0 || st.Blocks > math.MaxInt64/512 || v.AllocatedBytes > math.MaxInt64-st.Blocks*512 {\n\t\treturn fmt.Errorf("workspace allocation survey bound exceeded: %w", ErrUnknown)\n\t}\n\tv.Entries++\n\tv.AllocatedBytes += st.Blocks * 512\n\treturn nil\n}\n\n// SurveyWorkspace reads one exact marked workspace through held descriptors.\n// It refuses changed entries and crossings of the reported native mount\n// identity: Linux requires STATX_MNT_ID; Darwin pairs Fsid and Mntonname.\n// This is not an atomic snapshot against same-account writers, proof of\n// exclusive blocks, or cleanup authority.\nfunc SurveyWorkspace(ctx context.Context, selected, parent *Root, path string, want Reservation) (WorkspaceAllocation, error) {\n\tvar out WorkspaceAllocation\n\tif ctx == nil {\n\t\treturn out, ErrChanged\n\t}\n\tif err := ctx.Err(); err != nil {\n\t\treturn out, err\n\t}\n\tw, err := InspectWorkspace(selected, parent, path, want)\n\tif err != nil {\n\t\treturn out, err\n\t}\n\tdefer w.Close()\n\tparentMount, err := surveyMountFD(parent.FD())\n\tif err != nil {\n\t\treturn out, err\n\t}\n\tbaseMount, err := surveyMountFD(w.Base.FD())\n\tif err != nil || baseMount != parentMount {\n\t\treturn out, ErrChanged\n\t}\n\tbaseStat, err := statFD(w.Base.FD())\n\tif err != nil {\n\t\treturn out, err\n\t}\n\tfd, err := unix.Openat(w.Base.FD(), ".", unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)\n\tif err != nil {\n\t\treturn out, err\n\t}\n\tdir := os.NewFile(uintptr(fd), w.Base.Path())\n\tdefer dir.Close()\n\tscanStat, err := statFD(fd)\n\tif err != nil || !surveyStable(baseStat, scanStat) {\n\t\treturn out, ErrChanged\n\t}\n\tif err := out.add(baseStat); err != nil {\n\t\treturn WorkspaceAllocation{}, err\n\t}\n\tif err := surveyWorkspaceDirectory(ctx, dir, 0, uint64(baseStat.Dev), baseMount, &out); err != nil {\n\t\treturn WorkspaceAllocation{}, err\n\t}\n\tendStat, err := statFD(w.Base.FD())\n\tif err != nil || !surveyStable(baseStat, endStat) {\n\t\treturn WorkspaceAllocation{}, ErrChanged\n\t}\n\tfor _, root := range []*Root{selected, parent, w.Base, w.Stage, w.Quarantine} {\n\t\tif err := root.Check(); err != nil {\n\t\t\treturn WorkspaceAllocation{}, err\n\t\t}\n\t}\n\treturn out, nil\n}\n\nfunc surveyWorkspaceDirectory(ctx context.Context, dir *os.File, depth int, device uint64, mount string, out *WorkspaceAllocation) error {\n\tif depth > maxWorkspaceSurveyDepth {\n\t\treturn fmt.Errorf("workspace survey depth exceeded: %w", ErrUnknown)\n\t}\n\tif err := ctx.Err(); err != nil {\n\t\treturn err\n\t}\n\tcurrentMount, err := surveyMountFD(int(dir.Fd()))\n\tif err != nil || currentMount != mount {\n\t\treturn ErrChanged\n\t}\n\tfor {\n\t\tentries, readErr := dir.ReadDir(128)\n\t\tif readErr != nil && readErr != io.EOF {\n\t\t\treturn readErr\n\t\t}\n\t\tfor _, entry := range entries {\n\t\t\tif err := ctx.Err(); err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t\tname := entry.Name()\n\t\t\tif err := validComponent(name); err != nil {\n\t\t\t\treturn ErrChanged\n\t\t\t}\n\t\t\tbefore, err := statNamed(int(dir.Fd()), name)\n\t\t\tif err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t\tif uint64(before.Dev) != device || before.Uid != uint32(os.Geteuid()) {\n\t\t\t\treturn ErrChanged\n\t\t\t}\n\t\t\tkind := before.Mode & unix.S_IFMT\n\t\t\tif kind != unix.S_IFDIR && kind != unix.S_IFREG && kind != unix.S_IFLNK {\n\t\t\t\treturn ErrChanged\n\t\t\t}\n\t\t\tif kind != unix.S_IFLNK {\n\t\t\t\tchildMount, err := surveyMountAt(int(dir.Fd()), name)\n\t\t\t\tif err != nil || childMount != mount {\n\t\t\t\t\treturn ErrChanged\n\t\t\t\t}\n\t\t\t}\n\t\t\tif err := out.add(before); err != nil {\n\t\t\t\treturn err\n\t\t\t}\n\t\t\tif kind == unix.S_IFDIR {\n\t\t\t\tfd, err := unix.Openat(int(dir.Fd()), name, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_NOFOLLOW|unix.O_CLOEXEC, 0)\n\t\t\t\tif err != nil {\n\t\t\t\t\treturn err\n\t\t\t\t}\n\t\t\t\tchild := os.NewFile(uintptr(fd), name)\n\t\t\t\topened, openErr := statFD(fd)\n\t\t\t\tif openErr == nil && !surveyStable(before, opened) {\n\t\t\t\t\topenErr = ErrChanged\n\t\t\t\t}\n\t\t\t\tif openErr == nil {\n\t\t\t\t\topenErr = surveyWorkspaceDirectory(ctx, child, depth+1, device, mount, out)\n\t\t\t\t}\n\t\t\t\tcloseErr := child.Close()\n\t\t\t\tif openErr != nil {\n\t\t\t\t\treturn openErr\n\t\t\t\t}\n\t\t\t\tif closeErr != nil {\n\t\t\t\t\treturn closeErr\n\t\t\t\t}\n\t\t\t}\n\t\t\tafter, err := statNamed(int(dir.Fd()), name)\n\t\t\tif err != nil || !surveyStable(before, after) {\n\t\t\t\treturn ErrChanged\n\t\t\t}\n\t\t\tif kind != unix.S_IFLNK {\n\t\t\t\tchildMount, err := surveyMountAt(int(dir.Fd()), name)\n\t\t\t\tif err != nil || childMount != mount {\n\t\t\t\t\treturn ErrChanged\n\t\t\t\t}\n\t\t\t}\n\t\t}\n\t\tif readErr == io.EOF {\n\t\t\treturn nil\n\t\t}\n\t}\n}\n'
MOUNT_TEST='TestWorkspaceAllocationNativeLinuxPrivateBindMountRefusal'
def sha(b):return hashlib.sha256(b).hexdigest()
def check():
 files={n:sha((ROOT/n).read_bytes()) for n in subprocess.check_output(['git','ls-files','-z'],cwd=ROOT).decode().split('\0') if n and n not in EXCLUDE}
 assert files==EXPECTED,'reviewed source inputs changed'
 return files
mode=sys.argv[1];OUT.mkdir(parents=True,exist_ok=True);files=check()
if mode=='prepare':
 commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip()
 (OUT/'source-and-platform.json').write_text(json.dumps({'commit':commit,'platform':platform.platform(),'architecture':platform.machine(),'source_count':len(files),'source_digest':DIGEST,'tracked_sha256':files},indent=2)+'\n')
 (OUT/'original-linux.go').write_text(ORIGINAL_LINUX)
 (OUT/'original-linux-overlay.json').write_text(json.dumps({'Replace':{str(ROOT/'internal/syncfs/allocation.go'):str(OUT/'original-linux.go')}})+'\n')
 (OUT/'legacy-darwin.go').write_text(LEGACY_DARWIN)
 (OUT/'legacy-darwin-overlay.json').write_text(json.dumps({'Replace':{str(ROOT/'internal/syncfs/allocation_darwin.go'):str(OUT/'legacy-darwin.go')}})+'\n')
 (OUT/'legacy-darwin-policy.json').write_text(json.dumps({'meaning':'Prior Fsid-only return expression mechanically extracted at pure Statfs value seam; not an actual native same-filesystem Darwin mount','reference_sha256':sha(LEGACY_DARWIN.encode())},indent=2)+'\n')
elif mode=='assess':
 name,code=sys.argv[2],int(sys.argv[3]);log=OUT/(name+'.jsonl');raw=log.read_bytes();events=[json.loads(l) for l in raw.decode().splitlines() if l.startswith('{')];named=[e for e in events if e.get('Test') and e.get('Action') in ('pass','fail','skip')]
 (OUT/(name+'-receipt.json')).write_text(json.dumps({'name':name,'original_exit':code,'log_sha256':sha(raw),'source_unchanged':True,'terminal':{a:[{'package':e.get('Package'),'test':e.get('Test')} for e in events if e.get('Action')==a] for a in ['pass','fail','skip','build-fail']}},indent=2)+'\n')
 if name=='original-darwin':
  assert code==1 and any(e['Action']=='fail' and e['Test']=='TestWorkspaceAllocationDarwinMountIdentitySeparatesReportedMountpoints' for e in named),'prior Fsid-only policy did not fail pure value counterexample'
  assert 'same-filesystem reported mounts were conflated' in ''.join(e.get('Output','') for e in events),'unrelated original failure'
 elif name=='original-symlink':
  assert code==1 and any(e['Action']=='fail' and e['Test']==MOUNT_TEST+'/nested-symlink' for e in named),'original mounted-symlink counterexample did not fail'
  text=''.join(e.get('Output','') for e in events)
  assert 'same-device bind mount returned allocation evidence' in text and text.count('original private mount removed before exit; covered/outside snapshots unchanged')==1,'unrelated failure or unverified original mount cleanup'
 else:
  assert code==0 and not any(e.get('Action') in ('fail','build-fail') for e in events),'final native command failed'
  assert all(e['Action']=='pass' or name=='final-race' and platform.system()=='Linux' and e['Action']=='skip' and e['Test']==MOUNT_TEST for e in named),'unexpected named skip/failure'
  if name=='native-mount':assert sum(e['Action']=='pass' for e in named)==4,'native bind roots/cases not executed'
elif mode in ('binary-before','binary-after'):
 name=sys.argv[2];assert name in ('syncfs-original','syncfs-native');p=OUT/(name+'.test');image={'sha256':sha(p.read_bytes()),'bytes':p.stat().st_size}
 if mode=='binary-before':(OUT/(name+'-before.json')).write_text(json.dumps(image,indent=2)+'\n')
 else:
  assert json.loads((OUT/(name+'-before.json')).read_text())==image
  (OUT/(name+'-after.json')).write_text(json.dumps(image|{'same_original_image':True},indent=2)+'\n')
elif mode=='namespace-before':
 (OUT/'outer-namespace-before.json').write_text(json.dumps({'identity':os.readlink('/proc/self/ns/mnt'),'mountinfo_sha256':sha(pathlib.Path('/proc/self/mountinfo').read_bytes())},indent=2)+'\n')
elif mode=='namespace-after':
 before=json.loads((OUT/'outer-namespace-before.json').read_text());now={'identity':os.readlink('/proc/self/ns/mnt'),'mountinfo_sha256':sha(pathlib.Path('/proc/self/mountinfo').read_bytes())};assert before==now,'outer mount namespace changed';(OUT/'outer-namespace-after.json').write_text(json.dumps(now|{'same_original_namespace_and_catalog':True},indent=2)+'\n')
elif mode=='closure':
 names=['final-race','final-vet']+(['original-darwin'] if platform.system()=='Darwin' else ['original-symlink','native-mount'])
 for n in names:assert (OUT/(n+'-receipt.json')).is_file(),n
 if platform.system()=='Linux':
  assert all((OUT/(n+'-after.json')).is_file() for n in ('syncfs-original','syncfs-native')) and (OUT/'outer-namespace-after.json').is_file()
 (OUT/'closure.json').write_text(json.dumps({'completed':True,'source_unchanged':True,'source_digest':DIGEST,'commands':names,'linux_private_mount_executed':platform.system()=='Linux'},indent=2)+'\n')
else:raise SystemExit('unknown evidence mode')
